//! mars-wasm：把 mars-core 的 Engine 包成 WebAssembly，讓整個規劃系統在瀏覽器裡離線執行。
//! JSON 請求／回應格式與 docs/API.md 相同；二進位網格以 Uint8Array 回傳。

use mars_core::{
    World,
    engine::{Engine, EngineError, GridBytes, LayerQuery, ReplanReq, RouteReq, TrackReq},
    grid::Grid,
    localize::SimRequest,
    synth::{self, SynthSpec},
    world::ProcessedMeta,
};
use wasm_bindgen::prelude::*;

#[wasm_bindgen]
pub struct WasmEngine {
    inner: Engine,
}

fn err(e: EngineError) -> JsValue {
    JsValue::from_str(&e.to_json().to_string())
}

fn parse<T: serde::de::DeserializeOwned>(json: &str) -> Result<T, JsValue> {
    serde_json::from_str(json).map_err(|e| {
        JsValue::from_str(&format!(
            "{{\"error\":\"bad_request\",\"message\":\"{e}\"}}"
        ))
    })
}

/// 二進位網格：前 12 bytes 是 header（w: u32, h: u32, cell_m: f32，little-endian），後面是資料。
fn pack(g: GridBytes) -> Vec<u8> {
    let mut out = Vec::with_capacity(12 + g.bytes.len());
    out.extend_from_slice(&(g.w as u32).to_le_bytes());
    out.extend_from_slice(&(g.h as u32).to_le_bytes());
    out.extend_from_slice(&g.cell_m.to_le_bytes());
    out.extend_from_slice(&g.bytes);
    out
}

#[wasm_bindgen]
impl WasmEngine {
    /// 用合成地形建立引擎（seed 決定地形）。
    #[wasm_bindgen(constructor)]
    pub fn new(seed: u32) -> WasmEngine {
        let world = synth::generate(&SynthSpec {
            seed,
            ..SynthSpec::default()
        });
        WasmEngine {
            inner: Engine::new(world),
        }
    }

    /// 用前處理過的真實 DEM 建立引擎：meta.json 字串 + dem.f32 位元組。
    pub fn from_processed(meta_json: &str, dem_le_f32: &[u8]) -> Result<WasmEngine, JsValue> {
        let m: ProcessedMeta = parse(meta_json)?;
        if dem_le_f32.len() != m.width * m.height * 4 {
            return Err(JsValue::from_str("dem size does not match meta"));
        }
        let data = dem_le_f32
            .chunks_exact(4)
            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect();
        let world = World {
            name: m.name,
            source: m.source,
            dem: Grid::from_vec(m.width, m.height, m.cell_m, data),
            base: (m.base[0], m.base[1]),
            targets: m.targets,
            beacons: m.beacons,
        };
        Ok(WasmEngine {
            inner: Engine::new(world),
        })
    }

    pub fn meta(&self) -> String {
        self.inner.meta().to_string()
    }

    pub fn terrain(&self, step: usize) -> Vec<u8> {
        pack(self.inner.terrain(step))
    }

    /// query_json：{"step":4,"mode":"safe","x":..,"y":..,"o2_min":..}
    pub fn layer(&self, name: &str, query_json: &str) -> Result<Vec<u8>, JsValue> {
        let q: LayerQuery = parse(query_json)?;
        self.inner.layer(name, &q).map(pack).map_err(err)
    }

    pub fn route(&self, req_json: &str) -> Result<String, JsValue> {
        let r: RouteReq = parse(req_json)?;
        self.inner.route(&r).map(|v| v.to_string()).map_err(err)
    }

    pub fn compare(&self, req_json: &str) -> Result<String, JsValue> {
        let r: RouteReq = parse(req_json)?;
        self.inner.compare(&r).map(|v| v.to_string()).map_err(err)
    }

    pub fn replan(&self, req_json: &str) -> Result<String, JsValue> {
        let r: ReplanReq = parse(req_json)?;
        self.inner.replan(&r).map(|v| v.to_string()).map_err(err)
    }

    pub fn localize_sim(&self, req_json: &str) -> Result<String, JsValue> {
        let r: SimRequest = parse(req_json)?;
        Ok(self.inner.localize_sim(&r).to_string())
    }

    pub fn track(&self, req_json: &str) -> Result<String, JsValue> {
        let r: TrackReq = parse(req_json)?;
        self.inner.track(&r).map(|v| v.to_string()).map_err(err)
    }
}
